{"command": "cd /home/david12daniel/.openclaw/agents/thermal-surveillance-drone
# Check if purchaseUrl exists somewhere in each candidate's block
for p in $(grep '^  part [A-Z]' candidates.sysml | awk '{print $2}'); do
  # Find the line number where this part starts
  start=$(grep -n "^  part $p " candidates.sysml | head -1 | cut -d: -f1)
  # Find the closing }
  end=$(tail -n +$start candidates.sysml | grep -n "^  }" | head -1 | cut -d: -f1)
  end=$((start + end - 1))
  # Check if purchaseUrl is within this block
  if ! sed -n "${start},${end}p" candidates.sysml | grep -q purchaseUrl; then
    echo "MISSING: $p (lines $start-$end)"
  fi
done | head -30"}

{"command": "cd /home/david12daniel/.openclaw/agents/thermal-surveillance-drone
# Add purchaseUrl to TXM1-TXM5
for id in TXM1 TXM2 TXM3 TXM4 TXM5; do
  case "$id" in
    TXM1) url="https://www.radiomasterrc.com/products/ranger" ;;
    TXM2) url="https://www.radiomasterrc.com/products/ranger-micro" ;;
    TXM3) url="https://www.amazon.com/s?k=Happymodel+ES24TX+Pro" ;;
    TXM4) url="https://shop.iflight.com/" ;;
    TXM5) url="https://betafpv.com/" ;;
  esac
  python3 -c "
import re
with open('candidates.sysml', 'r') as f:
    c = f.read()
pat = re.compile(r'(  part $id : RadioControlTransmitter \{\n   :>> name = \"[^\"]+\";)')
m = pat.search(c)
if m:
    repl = m.group(1) + '\n   :>> purchaseUrl = \"$url\";'
    c = c[:m.start(1)] + repl + c[m.end(1):]
    with open('candidates.sysml', 'w') as f:
        f.write(c)
    print(f'Added URL to $id')
else:
    print(f'Could not find $id')
"
done"}
